TransferQueue<String> queue = new LinkedTransferQueue<>();

// ═══ put() — fire and forget ═══
queue.put("TXN-001");
// Returns immediately. TXN-001 is in the queue.
// Nobody may read it for hours. Producer doesn't care.

// ═══ transfer() — hand-off (blocks until received) ═══
// Thread-1 (producer):
queue.transfer("TXN-002");  // BLOCKS here until a consumer takes it!

// Thread-2 (consumer):
String txn = queue.take();   // receives "TXN-002" → Thread-1 unblocks!

// ═══ tryTransfer — non-blocking check ═══
boolean delivered = queue.tryTransfer("TXN-003");
// If a consumer is ALREADY waiting: delivered = true (instant hand-off)
// If no consumer waiting: delivered = false (element NOT queued!)

// ═══ tryTransfer with timeout ═══
boolean delivered2 = queue.tryTransfer("TXN-004", 5, TimeUnit.SECONDS);
// Waits up to 5 seconds for a consumer. Returns false if timeout.

// ═══ USE CASE: request-response pattern ═══
// Producer creates request, transfers it, BLOCKS until consumer processes it.
// When consumer takes it, producer knows it's being handled → can wait for result.
