package com.bank.transfer;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;

class TransferQueueTest {

    @Test
    void transfer_blocksUntilConsumed() throws InterruptedException {
        TransferQueue<String> queue = new LinkedTransferQueue<>();
        CountDownLatch transferred = new CountDownLatch(1);

        // Producer: transfer blocks until consumer takes
        Thread producer = new Thread(() -> {
            try {
                queue.transfer("TXN-001");  // blocks!
                transferred.countDown();     // only runs AFTER consumer takes
            } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        });

        producer.start();
        Thread.sleep(100);  // producer is blocking...
        assertThat(transferred.getCount()).isEqualTo(1);  // still blocked!

        String received = queue.take();  // consumer takes → producer unblocks!
        transferred.await(1, TimeUnit.SECONDS);
        assertThat(received).isEqualTo("TXN-001");
        assertThat(transferred.getCount()).isEqualTo(0);  // producer finished!
    }

    @Test
    void tryTransfer_noConsumer_returnsFalse() {
        TransferQueue<String> queue = new LinkedTransferQueue<>();
        boolean delivered = queue.tryTransfer("TXN-001");
        assertThat(delivered).isFalse();  // no consumer waiting!
        assertThat(queue).isEmpty();       // element NOT queued!
    }

    @Test
    void put_doesNotBlock() throws InterruptedException {
        TransferQueue<String> queue = new LinkedTransferQueue<>();
        queue.put("TXN-001");  // returns immediately!
        assertThat(queue).hasSize(1);  // element in queue, no consumer needed
    }
}
